#### Permission Implementation

```python
from dataclasses import dataclass
from typing import List, Dict, Optional
from enum import Enum

class Action(Enum):
    CREATE = "create"
    READ = "read"
    UPDATE = "update"
    DELETE = "delete"
    EXECUTE = "execute"

@dataclass
class Permission:
    resource: str
    actions: List[Action]
    constraints: Dict[str, any]
    scope: str = "tenant"

@dataclass
class Role:
    name: str
    description: str
    permissions: List[Permission]
    inherits_from: List[str] = None
    hierarchy_level: int = 0

class RoleManager:
    def __init__(self):
        self.roles = {}
        self.role_hierarchy = {}

    def define_role(self, role: Role) -> None:
        """Define a new role in the system"""
        self.roles[role.name] = role
        self._build_hierarchy()

    def get_effective_permissions(self, role_names: List[str]) -> List[Permission]:
        """Get all effective permissions for given roles including inherited"""
        permissions = []

        for role_name in role_names:
            role = self.roles.get(role_name)
            if role:
                # Add direct permissions
                permissions.extend(role.permissions)

                # Add inherited permissions
                if role.inherits_from:
                    inherited_permissions = self.get_effective_permissions(role.inherits_from)
                    permissions.extend(inherited_permissions)

        return self._deduplicate_permissions(permissions)
