#### Scope Validation Implementation

```python
from typing import Set, List
import re

class ScopeValidator:
    def __init__(self):
        self.scope_pattern = re.compile(r'^[a-z_]+:[a-z_]+:[a-z_]+$')
        self.valid_scopes = self._load_valid_scopes()

    def validate_scopes(self, requested_scopes: List[str], user_roles: List[str]) -> Set[str]:
        """Validate and filter scopes based on user roles"""
        valid_scopes = set()

        for scope in requested_scopes:
            if self._is_scope_format_valid(scope):
                if self._user_can_access_scope(scope, user_roles):
                    valid_scopes.add(scope)

        return valid_scopes

    def _is_scope_format_valid(self, scope: str) -> bool:
        """Check if scope follows naming convention"""
        return bool(self.scope_pattern.match(scope))

    def _user_can_access_scope(self, scope: str, user_roles: List[str]) -> bool:
        """Check if user roles allow access to scope"""
        resource, action, qualifier = scope.split(':')

        for role in user_roles:
            role_scopes = self._get_role_scopes(role)
            if scope in role_scopes:
                return True

            # Check for wildcard permissions
            wildcard_scope = f"{resource}:{action}:*"
            if wildcard_scope in role_scopes:
                return True

        return False
