#### Tenant Isolation Implementation

```python
from typing import Optional
from dataclasses import dataclass

@dataclass
class TenantContext:
    tenant_id: str
    tenant_type: str
    parent_tenant_id: Optional[str] = None
    allowed_resource_types: List[str] = None

class TenantAuthorizationService:
    def __init__(self):
        self.tenant_hierarchy = {}
        self.tenant_policies = {}

    def check_tenant_access(
        self,
        user_tenant_id: str,
        resource_tenant_id: str,
        user_roles: List[str]
    ) -> bool:
        """Check if user can access resources in target tenant"""

        # Same tenant access
        if user_tenant_id == resource_tenant_id:
            return True

        # Check for cross-tenant roles (e.g., SecurityAdmin)
        if self._has_cross_tenant_role(user_roles):
            return True

        # Check tenant hierarchy (parent-child relationships)
        if self._is_parent_tenant(user_tenant_id, resource_tenant_id):
            return self._has_parent_access_role(user_roles)

        return False

    def filter_resources_by_tenant(
        self,
        resources: List[Dict],
        user_tenant_id: str,
        user_roles: List[str]
    ) -> List[Dict]:
        """Filter resources based on tenant access permissions"""

        filtered_resources = []

        for resource in resources:
            resource_tenant_id = resource.get('tenant_id')

            if self.check_tenant_access(user_tenant_id, resource_tenant_id, user_roles):
                filtered_resources.append(resource)

        return filtered_resources

    def _has_cross_tenant_role(self, roles: List[str]) -> bool:
        """Check if user has roles that allow cross-tenant access"""
        cross_tenant_roles = ['SecurityAdmin']
        return any(role in cross_tenant_roles for role in roles)
