### 5.1 Automated Testing

Comprehensive authorization testing strategy:

```python
import pytest
from unittest.mock import Mock, patch
from authorization_service import AuthorizationService

class TestAuthorization:
    @pytest.fixture
    def auth_service(self):
        return AuthorizationService()

    @pytest.fixture
    def user_context(self):
        return {
            "user_id": "user123",
            "tenant_id": "tenant456",
            "roles": ["BusinessAdministrator"],
            "scopes": ["users:read:all", "users:write:all"]
        }

    async def test_user_admin_can_manage_users(self, auth_service, user_context):
        # Test read permission
        assert await auth_service.check_permission(
            user_context,
            "users",
            "read",
            {"tenant_id": "tenant456"}
        )

        # Test write permission
        assert await auth_service.check_permission(
            user_context,
            "users",
            "create",
            {"tenant_id": "tenant456"}
        )

    async def test_cross_tenant_access_denied(self, auth_service, user_context):
        # Should deny access to different tenant
        assert not await auth_service.check_permission(
            user_context,
            "users",
            "read",
            {"tenant_id": "other_tenant"}
        )

    async def test_insufficient_scope_denied(self, auth_service):
        limited_context = {
            "user_id": "user123",
            "tenant_id": "tenant456",
            "roles": ["UserViewer"],
            "scopes": ["users:read:basic"]
        }

        # Should deny write access with read-only scope
        assert not await auth_service.check_permission(
            limited_context,
            "users",
            "create",
            {"tenant_id": "tenant456"}
        )
